check:
cp deploy/service.conf deploy/service.conf.orig || exit 1
sed -i.bak 's/^listen_address=.*/listen_address=127.0.0.1:9199/' deploy/service.conf
if ! grep -q '^listen_address=127.0.0.1:9199$' deploy/service.conf; then
  echo "probe could not mutate the deployment config" >&2
  exit 1
fi
if ! grep -q 'resolveListenAddr' main.go; then
  echo "main.go does not use resolveListenAddr" >&2
  exit 1
fi
cat > probe_listen_addr_test.go <<'EOF'
package main

import (
	"os"
	"regexp"
	"testing"
)

func TestProbeResolveListenAddr(t *testing.T) {
	raw, err := os.ReadFile("deploy/service.conf")
	if err != nil {
		t.Fatalf("read config: %v", err)
	}
	m := regexp.MustCompile(`(?m)^\s*listen_address\s*=\s*(\S+)\s*$`).FindSubmatch(raw)
	if m == nil {
		t.Fatalf("config has no listen_address line: %q", raw)
	}
	addr, err := resolveListenAddr()
	if err != nil {
		t.Fatalf("resolveListenAddr: %v", err)
	}
	if addr != string(m[1]) {
		t.Fatalf("resolveListenAddr = %q, want %q", addr, string(m[1]))
	}
}
EOF
go test -count=1 -run TestProbeResolveListenAddr .
rc=$?
mv -f deploy/service.conf.bak deploy/service.conf 2>/dev/null
rm -f probe_listen_addr_test.go
exit $rc

